import{c as t,Q as s,j as e,m as l}from"./chunks/framework.BPKcPtvA.js";const i="/screenshots/shops.png",n="/screenshots/shop-detail.png",b=JSON.parse('{"title":"ショップ画面","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shops.md","filePath":"guide/shops.md","lastUpdated":1786391114000}'),o={name:"guide/shops.md"};function r(d,a,p,h,c,u){return s(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="ショップ画面" tabindex="-1">ショップ画面 <a class="header-anchor" href="#ショップ画面" aria-label="Permalink to &quot;ショップ画面&quot;">​</a></h1><p>ライブラリの購入アイテムを <strong>ショップ単位</strong> でまとめて見れる画面です。 さらに BOOTH の「フォロー中ショップ」を取り込んで、新作が出たら通知できます。</p><p><img src="'+i+`" alt="ショップ画面 — サブタブとショップカードの一覧"></p><blockquote><p>画面内のショップ名・ハンドルはデモ用の架空データです。</p></blockquote><h2 id="サブタブ" tabindex="-1">サブタブ <a class="header-anchor" href="#サブタブ" aria-label="Permalink to &quot;サブタブ&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[すべて (87)] [★ フォロー中 (70)] [ライブラリ (45)]    [↺]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>タブ</th><th>内容</th></tr></thead><tbody><tr><td>すべて</td><td>ライブラリ内 + フォロー中ショップ (= 購入無しでも見える)</td></tr><tr><td>★ フォロー中</td><td>BOOTH 側でフォローしているショップだけ</td></tr><tr><td>ライブラリ</td><td>ライブラリに購入アイテムがあるショップだけ</td></tr><tr><td>↺ (取得ボタン)</td><td>BOOTH のフォロー中ショップ一覧を取得して同期 (= 後述)</td></tr></tbody></table><h2 id="ショップカード" tabindex="-1">ショップカード <a class="header-anchor" href="#ショップカード" aria-label="Permalink to &quot;ショップカード&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────┐</span></span>
<span class="line"><span>│  ┌──┐ ショップ名 ✓           │  ✓: 公式検証済バッジ</span></span>
<span class="line"><span>│  │🏪│ @ハンドル               │</span></span>
<span class="line"><span>│  └──┘ 12 アイテム             │</span></span>
<span class="line"><span>└──────────────────────────────┘</span></span>
<span class="line"><span>   ★ ← フォロー中 (アイコン右下にバッジ)</span></span></code></pre></div><ul><li>フォロー中のショップはアイコン右下に <strong>★ バッジ</strong></li><li>ライブラリに購入アイテム 0 件のフォロー中ショップは「ライブラリ内 0 アイテム」と表示 (薄く表示)</li><li>クリックで <strong>ショップ詳細</strong> (購入済みアイテムがある場合) または <strong>BOOTH を外部で開く</strong> (購入が無く、フォローのみの場合)</li><li>一覧の並び順は <strong>フォロー中 → アイテム数の多い順 → 名前順</strong></li></ul><h2 id="ショップ詳細画面" tabindex="-1">ショップ詳細画面 <a class="header-anchor" href="#ショップ詳細画面" aria-label="Permalink to &quot;ショップ詳細画面&quot;">​</a></h2><p>ショップカードをクリックすると、そのショップから買ったアイテム一覧が出ます。</p><p><img src="`+n+'" alt="ショップ詳細画面 — 大きいアイコン + 購入アイテムのタイル一覧"></p><ul><li>大きいアイコン + ショップ名 + 「BOOTH で開く」ボタン</li><li>@ハンドルの横に <strong>作者名</strong> を表示 (例: <code>@handle (うのいず)</code>)。BOOTH のショップページから取得し、約 30 日キャッシュします</li><li>下に正方形のタイル一覧 (商品サムネ + 名前) で全購入アイテム</li><li>タイルクリックで <a href="/guide/library-detail">商品詳細画面</a> へ移動</li></ul><h2 id="r-18-表示との連動" tabindex="-1">R-18 表示との連動 <a class="header-anchor" href="#r-18-表示との連動" aria-label="Permalink to &quot;R-18 表示との連動&quot;">​</a></h2><p>ライブラリ画面の <strong>R-18 表示</strong> を OFF にすると、ショップタブにも反映されます。</p><ul><li>各ショップの <strong>アイテム件数</strong> と <strong>詳細のタイル一覧</strong> から R-18 商品が除かれます</li><li>全アイテムが R-18 のショップは一覧から消えます (フォロー中のショップは「ライブラリ内 0 アイテム」として残ります)</li></ul><h2 id="booth-フォロー機能" tabindex="-1">BOOTH フォロー機能 <a class="header-anchor" href="#booth-フォロー機能" aria-label="Permalink to &quot;BOOTH フォロー機能&quot;">​</a></h2><h3 id="「☆-フォロー」ボタン" tabindex="-1">「☆ フォロー」ボタン <a class="header-anchor" href="#「☆-フォロー」ボタン" aria-label="Permalink to &quot;「☆ フォロー」ボタン&quot;">​</a></h3><p>ライブラリの商品カードを開いて出てくる <strong>ショップ詳細パネル</strong> (ショップ名クリック) には <strong>「☆ フォロー」</strong> ボタンがあります。</p><ul><li>クリックで BOOTH 側にもフォローを反映</li><li>同時に手元のデータにも追加</li><li>もう一度クリックでフォロー解除</li></ul><h3 id="一括同期-↺-ボタン" tabindex="-1">一括同期 (↺ ボタン) <a class="header-anchor" href="#一括同期-↺-ボタン" aria-label="Permalink to &quot;一括同期 (↺ ボタン)&quot;">​</a></h3><p>ショップタブの ↺ ボタンで、フォロー中ショップの一覧を同期し、新着商品を確認します:</p><ol><li>フォロー中ショップの名前とアイコンを取り込み、ショップカードを順次表示</li><li>フォロー中ショップの新着商品を確認</li><li>完了メッセージに「新規 N 件 追加 / 既存 M 件 / 新着 K 件」を表示</li></ol><p>同期中の手順と進み具合は <a href="/guide/background-tasks#どこから確認する">バックグラウンドタスク</a> で確認でき、そこから中止もできます。</p><h3 id="自動同期-起動時" tabindex="-1">自動同期 (起動時) <a class="header-anchor" href="#自動同期-起動時" aria-label="Permalink to &quot;自動同期 (起動時)&quot;">​</a></h3><p>初回起動時や、最後の確認から設定した時間が経過したときは、起動後に自動で同期します。</p><p>「24 時間」は <strong>設定</strong> で変更できます (1〜168 時間 = 1 時間〜7 日)。</p><h3 id="新着通知" tabindex="-1">新着通知 <a class="header-anchor" href="#新着通知" aria-label="Permalink to &quot;新着通知&quot;">​</a></h3><p>フォロー中ショップの新着商品を確認し、まだ確認していないものを通知ベルへ追加します。</p><ul><li>通知パネル (右下 🔔) に「🏪 ショップ名 新着」+ 商品名 + サムネ</li><li>通知行クリックで BOOTH 商品ページを外部ブラウザで開く</li><li><strong>初回の取り込み時は通知を出しません</strong></li></ul><h2 id="制限" tabindex="-1">制限 <a class="header-anchor" href="#制限" aria-label="Permalink to &quot;制限&quot;">​</a></h2><ul><li>1 回に同期できるフォロー中ショップは最大 1,000 件です</li><li>新着確認は 1 回につき約 500 商品までです。前回の確認から 500 件を超える 新着があると、それより古い未確認の商品を取りこぼす場合があります</li><li>BOOTH 側でフォロー解除してもアプリの一覧には残ります。削除するには、ショップ詳細パネルの「★ フォロー中」を切り替えてください</li></ul>',33)])])}const m=t(o,[["render",r]]);export{b as __pageData,m as default};
